#!/usr/bin/env python3\n\"\"\"\nTeste Rápido da Página de Relatórios\n===================================\n\nScript para testar se todos os componentes da página de relatórios \nestão implementados corretamente.\n\"\"\"\n\nimport sys\nimport os\nsys.path.append(os.path.dirname(os.path.abspath(__file__)))\n\ndef test_imports():\n    \"\"\"Testa se todos os imports estão funcionando\"\"\"\n    try:\n        print(\"🧪 Testando imports...\")\n        \n        # Testa layout\n        from layout.relatorios import create_relatorios_layout\n        print(\"✅ Layout de relatórios importado com sucesso\")\n        \n        # Testa callbacks\n        from callbacks.relatorios_callbacks import register_relatorios_callbacks\n        print(\"✅ Callbacks de relatórios importados com sucesso\")\n        \n        # Testa queries\n        from services.queries import ReportsQueries\n        print(\"✅ ReportsQueries importada com sucesso\")\n        \n        # Testa componentes\n        from components.cards import create_chart_card\n        from components.nav import create_page_header\n        from components.tables import create_data_table\n        print(\"✅ Componentes auxiliares importados com sucesso\")\n        \n        return True\n        \n    except ImportError as e:\n        print(f\"❌ Erro de import: {e}\")\n        return False\n    except Exception as e:\n        print(f\"❌ Erro geral: {e}\")\n        return False\n\ndef test_layout_creation():\n    \"\"\"Testa se o layout pode ser criado\"\"\"\n    try:\n        print(\"\\n🧪 Testando criação do layout...\")\n        \n        from layout.relatorios import create_relatorios_layout\n        layout = create_relatorios_layout()\n        \n        if layout:\n            print(\"✅ Layout criado com sucesso\")\n            return True\n        else:\n            print(\"❌ Layout não foi criado\")\n            return False\n            \n    except Exception as e:\n        print(f\"❌ Erro ao criar layout: {e}\")\n        return False\n\ndef test_queries():\n    \"\"\"Testa se as queries funcionam (com dados mock)\"\"\"\n    try:\n        print(\"\\n🧪 Testando queries...\")\n        \n        from services.queries import ReportsQueries\n        \n        # Testa query de conversas\n        conv_report = ReportsQueries.get_conversations_report(limit=5)\n        if conv_report and 'data' in conv_report:\n            print(f\"✅ Query de conversas funcionando - {len(conv_report['data'])} registros\")\n        else:\n            print(\"❌ Query de conversas com problema\")\n            return False\n            \n        # Testa query de agendamentos\n        apt_report = ReportsQueries.get_appointments_report(limit=5)\n        if apt_report and 'data' in apt_report:\n            print(f\"✅ Query de agendamentos funcionando - {len(apt_report['data'])} registros\")\n        else:\n            print(\"❌ Query de agendamentos com problema\")\n            return False\n            \n        # Testa query de analytics\n        analytics = ReportsQueries.get_analytics_data(period_days=7)\n        if analytics and 'timeline' in analytics:\n            print(f\"✅ Query de analytics funcionando - {len(analytics['timeline'])} pontos\")\n        else:\n            print(\"❌ Query de analytics com problema\")\n            return False\n            \n        return True\n        \n    except Exception as e:\n        print(f\"❌ Erro ao testar queries: {e}\")\n        return False\n\ndef test_css_exists():\n    \"\"\"Testa se o arquivo CSS foi criado\"\"\"\n    try:\n        print(\"\\n🧪 Testando arquivo CSS...\")\n        \n        css_path = \"assets/relatorios_modern.css\"\n        if os.path.exists(css_path):\n            with open(css_path, 'r') as f:\n                css_content = f.read()\n                if len(css_content) > 1000:  # CSS deve ter conteúdo significativo\n                    print(f\"✅ CSS criado com sucesso - {len(css_content)} caracteres\")\n                    return True\n                else:\n                    print(\"❌ CSS muito pequeno\")\n                    return False\n        else:\n            print(\"❌ Arquivo CSS não encontrado\")\n            return False\n            \n    except Exception as e:\n        print(f\"❌ Erro ao verificar CSS: {e}\")\n        return False\n\ndef test_app_integration():\n    \"\"\"Testa se a integração no app.py está correta\"\"\"\n    try:\n        print(\"\\n🧪 Testando integração no app.py...\")\n        \n        with open('app.py', 'r') as f:\n            app_content = f.read()\n            \n        # Verifica se CSS está incluído\n        if 'relatorios_modern.css' in app_content:\n            print(\"✅ CSS incluído no app.py\")\n        else:\n            print(\"❌ CSS não incluído no app.py\")\n            return False\n            \n        # Verifica se callbacks estão registrados\n        if 'register_relatorios_callbacks' in app_content:\n            print(\"✅ Callbacks registrados no app.py\")\n        else:\n            print(\"❌ Callbacks não registrados no app.py\")\n            return False\n            \n        # Verifica se rota existe\n        if '/relatorios' in app_content:\n            print(\"✅ Rota /relatorios configurada\")\n        else:\n            print(\"❌ Rota /relatorios não configurada\")\n            return False\n            \n        return True\n        \n    except Exception as e:\n        print(f\"❌ Erro ao verificar integração: {e}\")\n        return False\n\ndef run_tests():\n    \"\"\"Executa todos os testes\"\"\"\n    print(\"🚀 Iniciando testes da página de Relatórios...\\n\")\n    \n    tests = [\n        (\"Imports\", test_imports),\n        (\"Layout Creation\", test_layout_creation),\n        (\"Queries\", test_queries),\n        (\"CSS File\", test_css_exists),\n        (\"App Integration\", test_app_integration)\n    ]\n    \n    results = []\n    \n    for test_name, test_func in tests:\n        result = test_func()\n        results.append((test_name, result))\n    \n    # Relatório final\n    print(\"\\n\" + \"=\"*50)\n    print(\"📊 RELATÓRIO DOS TESTES\")\n    print(\"=\"*50)\n    \n    passed = 0\n    total = len(results)\n    \n    for test_name, result in results:\n        status = \"✅ PASSOU\" if result else \"❌ FALHOU\"\n        print(f\"{test_name:<20} {status}\")\n        if result:\n            passed += 1\n    \n    print(f\"\\n🎯 Resultado: {passed}/{total} testes passaram\")\n    \n    if passed == total:\n        print(\"🎉 TODOS OS TESTES PASSARAM! A página de Relatórios está funcionando!\")\n        print(\"\\n🚀 Para testar no navegador:\")\n        print(\"   python app.py\")\n        print(\"   http://localhost:8050/relatorios\")\n    else:\n        print(f\"⚠️  {total - passed} testes falharam. Verifique os erros acima.\")\n    \n    return passed == total\n\nif __name__ == \"__main__\":\n    success = run_tests()\n    sys.exit(0 if success else 1)\n